int write_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_BASE && addr < (PSW_BASE + sizeof(psw_t))) {
        /* Processor status word register range */
        if (sizeof(psw_t) * 8 < data) {
            return -EINVAL;
        }
        *(psw_t *)((char *)child->regs + addr - PSW_BASE) = (psw_t)data;
    } else if (addr >= GPRS_BASE && addr < (GPRS_BASE + sizeof(gpr_t) * 16)) {
        /* General purpose register range */
        int reg_idx = (addr - GPRS_BASE) / sizeof(gpr_t);
        if (reg_idx < 0 || reg_idx >= 16) {
            return -EINVAL;
        }
        if (sizeof(gpr_t) * 8 < data) {
            return -EINVAL;
        }
        child->regs->gprs[reg_idx] = (gpr_t)data;
    } else if (addr >= FPRS_BASE && addr < (FPRS_BASE + sizeof(fpr_t) * 16)) {
        /* Floating point register range */
        int reg_idx = (addr - FPRS_BASE) / sizeof(fpr_t);
        if (reg_idx < 0 || reg_idx >= 16) {
            return -EINVAL;
        }
        if (sizeof(fpr_t) * 8 < data) {
            return -EINVAL;
        }
        child->regs->fprs[reg_idx] = (fpr_t)data;
    } else if (addr == PERINFO_ADDR) {
        /* Special handling for per_info structure */
        if (sizeof(per_info_t) < data) {
            return -EINVAL;
        }
        *(per_info_t *)((char *)child->regs + addr - PERINFO_ADDR) = (per_info_t)data;
    } else {
        return -EINVAL;
    }
    return 0;
}

int write_child_task_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= TASK_PSW_START && addr < (TASK_PSW_START + sizeof(psw_t))) {
        psw_t *psw = (psw_t *)((char *)child + addr);
        if (sizeof(psw_t) != sizeof(data))
            return -EINVAL;
        *psw = data;
    } else if (addr >= TASK_GPRS_START && addr < (TASK_GPRS_START + sizeof(gpr_t) * GPR_COUNT)) {
        gpr_t *gpr = (gpr_t *)((char *)child + addr);
        if (sizeof(gpr_t) != sizeof(data) && sizeof(gpr_t) != sizeof(data) * 2)
            return -EINVAL;
        *gpr = data;
    } else if (addr >= TASK_FPRS_START && addr < (TASK_FPRS_START + sizeof(fpr_t) * FPR_COUNT)) {
        fpr_t *fpr = (fpr_t *)((char *)child + addr);
        if (sizeof(fpr_t) != sizeof(data))
            return -EINVAL;
        *fpr = data;
    } else if (addr == TASK_PER_INFO_ADDR) {
        per_info_t *per_info = (per_info_t *)((char *)child + addr);
        if (sizeof(per_info_t) != sizeof(data))
            return -EINVAL;
        *per_info = data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_task_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_ADDR_START && addr < PSW_ADDR_END) {
        if (data > MAX_PSW_VALUE)
            return -EINVAL;
        child->regs.psw = data;
    } else if (addr >= GPRS_ADDR_START && addr < GPRS_ADDR_END) {
        if (addr % sizeof(addr_t) != 0)
            return -EINVAL;
        if (addr == GPRS_ADDR_64BIT) {
            if (data > MAX_64BIT_REG_VALUE)
                return -EINVAL;
        }
        child->regs.gprs[addr / sizeof(addr_t)] = data;
    } else if (addr >= FPRS_ADDR_START && addr < FPRS_ADDR_END) {
        if (addr % sizeof(double) != 0)
            return -EINVAL;
        child->regs.fprs[addr / sizeof(double)] = (double)data;
    } else if (addr == PER_INFO_ADDR) {
        child->regs.per_info = data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_child_task_register(struct task_struct *child, addr_t addr, addr_t data) {
    if ((addr >= 0 && addr < 16) || (addr >= 16 && addr < 32)) {
        /* General purpose registers or psw */
        if (addr == 15) {
            /* psw handling */
            if ((data & 0xFFFFFFFF00000000ULL) != 0) {
                return -EINVAL;
            }
        } else if (addr < 16) {
            /* gprs */
            if ((addr % 2) == 1) {
                /* Padding hole */
                return -EINVAL;
            }
        }
        *(addr_t *)((char *)&child->regs + addr) = data;
    } else if (addr >= 32 && addr < 64) {
        /* Floating-point registers */
        if ((addr % 2) == 1) {
            /* Padding hole */
            return -EINVAL;
        }
        *(addr_t *)((char *)&child->fpu + (addr - 32)) = data;
    } else if (addr >= 64 && addr < 80) {
        /* per_info */
        if ((addr % 2) == 1) {
            /* Padding hole */
            return -EINVAL;
        }
        *(addr_t *)((char *)&child->per_info + (addr - 64)) = data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_task_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (addr >= PSW_ADDR_MIN && addr <= PSW_ADDR_MAX) {
        /* Valid psw address range */
        if (data > MAX_PSW_VALUE)
            return -EINVAL;
        /* Write 64-bit psw data */
        *(addr_t *)((char *)child + addr) = data;
    } else if (addr >= GPRS_ADDR_MIN && addr <= GPRS_ADDR_MAX) {
        /* Valid general purpose register range */
        if (addr % sizeof(addr_t) != 0) {
            /* Prevent writes to padding holes */
            return -EINVAL;
        }
        *(addr_t *)((char *)child + addr) = data;
    } else if (addr >= FP_REGS_ADDR_MIN && addr <= FP_REGS_ADDR_MAX) {
        /* Valid floating-point registers range */
        if (data > MAX_FP_VALUE)
            return -EINVAL;
        *(addr_t *)((char *)child + addr) = data;
    } else if (addr == PER_INFO_OFFSET) {
        /* Special handling for per_info structure */
        if (data > MAX_PER_INFO_VALUE)
            return -EINVAL;
        *(addr_t *)((char *)child + addr) = data;
    } else {
        /* Address not valid */
        return -EINVAL;
    }

    return 0;
}
